struct Storage { counter: uint32; owner: address }
fun Storage.load() { return Storage.fromCell(contract.getData()) }
fun Storage.save(self) { contract.setData(self.toCell()) }
struct (0x7e8764ef) IncreaseCounter { queryId: uint64; increaseBy: uint32 }
fun onInternalMessage(in: InMessage) {
  val msg = lazy IncreaseCounter.fromSlice(in.body);
  var s = lazy Storage.load();
  s.counter += msg.increaseBy;
  s.save();
}
get fun currentCounter(): int { val s = lazy Storage.load(); return s.counter; }
get fun owner(): address { return Storage.load().owner; }
